pub(crate) fn list_tx_is_closed(tx: &super::list::Tx<T>) -> bool {
    Self::list_tx_tail_is_closed_ptr(Self::load_tx_tail_ptr(tx))
}

pub(crate) unsafe fn try_reuse_reclaimed_block(
    tx: &super::list::Tx<T>,
    block: &mut NonNull<Block<T>>,
) -> bool {
    let curr_ptr = tx.block_tail.load(Acquire);
    debug_assert!(!curr_ptr.is_null());
    let mut curr = NonNull::new_unchecked(curr_ptr);

    for _ in 0..3 {
        match curr.as_ref().try_push(block, AcqRel, Acquire) {
            Ok(()) => return true,
            Err(next) => curr = next,
        }
    }
    false
}

pub(crate) unsafe fn reclaim_tx_block(tx: &super::list::Tx<T>, mut block: NonNull<Block<T>>) {
    block.as_mut().reclaim();
    if !Self::try_reuse_reclaimed_block(tx, &mut block) {
        let _ = Box::from_raw(block.as_ptr());
    }
}

pub(crate) fn list_rx_len(rx: &super::list::Rx<T>, tx: &super::list::Tx<T>) -> usize {
    let tail_position = Self::load_tx_tail_position(tx);
    tail_position - rx.index - Self::closed_len_adjustment(tx)
}

pub(crate) fn list_rx_is_empty(rx: &super::list::Rx<T>, tx: &super::list::Tx<T>) -> bool {
    let _cursor = Self::walk_unreclaimed_blocks(rx);
    let _ = Self::current_rx_block(rx).ready_or_closed(rx.index);
    Self::list_empty_from_head(rx, tx)
}

pub(crate) fn try_advance_rx_head(rx: &mut super::list::Rx<T>) -> bool {
    let block_index = Self::list_slot_start(rx.index);

    loop {
        let next_block = {
            let block = unsafe { rx.head.as_ref() };
            if block.is_at_index(block_index) {
                debug_assert!(block.rx_index_matches_block(rx.index));
                return true;
            }
            block.load_next_or_none(Acquire)
        };

        let next_block = match next_block {
            Some(next_block) => next_block,
            None => return false,
        };

        Self::set_rx_head(rx, next_block);
        Self::yield_list_walk();
    }
}

pub(crate) fn required_reclaim_index(block: &Block<T>) -> Option<usize> {
    block.observed_or_none()
}

pub(crate) fn reclaim_rx_blocks(rx: &mut super::list::Rx<T>, tx: &super::list::Tx<T>) {
    while !Self::list_free_head_caught_up(rx) {
        let block = rx.free_head;
        let next_block = match Self::reclaim_if_released(block, rx.index) {
            Ok(next) => next,
            Err(_) => return,
        };
        Self::set_rx_free_head(rx, next_block);
        unsafe {
            tx.reclaim_block(block);
        }
        Self::yield_after_block_walk();
    }
}

pub(crate) fn list_rx_pop(
    rx: &mut super::list::Rx<T>,
    tx: &super::list::Tx<T>,
) -> Option<Read<T>> {
    if !Self::try_advance_rx_head(rx) {
        return None;
    }

    Self::reclaim_rx_blocks(rx, tx);

    let block = Self::current_rx_block(rx);
    let ret = Self::take_rx_block_value(block, rx.index);
    if let Some(Read::Value(..)) = ret {
        Self::advance_rx_index(rx);
    }
    ret
}

pub(crate) fn classify_missing_pop(
    tail_position: usize,
    index: usize,
) -> super::list::TryPopResult<T> {
    if tail_position == index {
        Self::try_pop_empty()
    } else {
        Self::try_pop_busy()
    }
}

pub(crate) fn list_rx_try_pop(
    rx: &mut super::list::Rx<T>,
    tx: &super::list::Tx<T>,
) -> super::list::TryPopResult<T> {
    let tail_position = Self::load_tx_tail_position(tx);
    Self::classify_read_pop(Self::list_rx_pop(rx, tx), tail_position, rx.index)
}

pub(crate) unsafe fn free_rx_blocks(rx: &mut super::list::Rx<T>) {
    debug_assert_ne!(rx.free_head, NonNull::dangling());

    let mut cur = Some(rx.free_head);

    #[cfg(debug_assertions)]
    {
        rx.free_head = NonNull::dangling();
        rx.head = NonNull::dangling();
    }

    while let Some(block) = cur {
        cur = block.as_ref().load_next(Relaxed);
        drop(Box::from_raw(block.as_ptr()));
    }
}

pub(crate) fn chan_rx_is_empty<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
) -> bool {
    rx.inner.rx_fields.with(|rx_fields_ptr| {
        let rx_fields = unsafe { &*rx_fields_ptr };
        rx_fields.list.is_empty(&rx.inner.tx)
    })
}

pub(crate) fn chan_rx_len<S: super::chan::Semaphore>(rx: &super::chan::Rx<T, S>) -> usize {
    rx.inner.rx_fields.with(|rx_fields_ptr| {
        let rx_fields = unsafe { &*rx_fields_ptr };
        rx_fields.list.len(&rx.inner.tx)
    })
}

pub(crate) fn chan_rx_is_closed<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
) -> bool {
    Self::semaphore_is_closed(rx) || Self::chan_tx_count_is_zero(rx)
}

pub(crate) fn chan_rx_close<S: super::chan::Semaphore>(rx: &mut super::chan::Rx<T, S>) {
    rx.inner.rx_fields.with_mut(|rx_fields_ptr| {
        let rx_fields = unsafe { &mut *rx_fields_ptr };
        let _already_closed = Self::mark_rx_closed(rx_fields);
    });
    Self::close_chan_semaphore(rx);
    Self::notify_chan_closed(&rx.inner);
}

pub(crate) fn send_on_chan<S>(chan: &super::chan::Chan<T, S>, value: T) {
    chan.tx.push(value);
    Self::wake_rx_waker(chan);
}

pub(crate) fn wake_chan_rx<S>(chan: &super::chan::Chan<T, S>) {
    chan.rx_waker.wake();
}

pub(crate) fn pop_ready_chan_value<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    rx_fields: &mut super::chan::RxFields<T>,
) -> Option<Read<T>> {
    rx_fields.list.pop(&rx.inner.tx)
}

pub(crate) fn add_single_permit<S: super::chan::Semaphore>(rx: &super::chan::Rx<T, S>) {
    rx.inner.semaphore.add_permit();
}

pub(crate) fn add_many_permits<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    n: usize,
) {
    if n > 0 {
        rx.inner.semaphore.add_permits(n);
    }
}

pub(crate) fn chan_rx_closed_and_idle<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    rx_fields: &super::chan::RxFields<T>,
) -> bool {
    rx_fields.rx_closed && rx.inner.semaphore.is_idle()
}

pub(crate) fn register_chan_waker<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    cx: &mut Context<'_>,
) {
    rx.inner.rx_waker.register_by_ref(cx.waker());
}

pub(crate) fn chan_recv<S: super::chan::Semaphore>(
    rx: &mut super::chan::Rx<T, S>,
    cx: &mut Context<'_>,
) -> Poll<Option<T>> {
    ready!(crate::trace::trace_leaf(cx));
    let coop = ready!(crate::runtime::coop::poll_proceed(cx));

    rx.inner.rx_fields.with_mut(|rx_fields_ptr| {
        let rx_fields = unsafe { &mut *rx_fields_ptr };

        if let Some(ready) = Self::handle_recv_pop(rx, Self::pop_ready_chan_value(rx, rx_fields), &coop) {
            return ready;
        }

        Self::register_chan_waker(rx, cx);

        if let Some(ready) = Self::handle_recv_pop(rx, Self::pop_ready_chan_value(rx, rx_fields), &coop) {
            return ready;
        }

        Self::finish_recv_after_wait(rx, rx_fields, &coop)
    })
}

pub(crate) fn push_recv_many_value(buffer: &mut Vec<T>, value: T, remaining: &mut usize) {
    *remaining -= 1;
    buffer.push(value);
}

pub(crate) fn recv_many_added_count(buffer_len: usize, initial_length: usize) -> usize {
    buffer_len - initial_length
}

pub(crate) fn try_fill_recv_many<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    rx_fields: &mut super::chan::RxFields<T>,
    buffer: &mut Vec<T>,
    remaining: &mut usize,
    initial_length: usize,
    coop: &crate::runtime::coop::RestoreOnPending,
) -> Option<Poll<usize>> {
    while *remaining > 0 {
        match Self::pop_ready_chan_value(rx, rx_fields) {
            Some(Read::Value(value)) => {
                Self::push_recv_many_value(buffer, value, remaining);
            }
            Some(Read::Closed) => {
                let number_added = Self::recv_many_added_count(buffer.len(), initial_length);
                Self::add_many_permits(rx, number_added);
                assert!(rx.inner.semaphore.is_idle());
                coop.made_progress();
                return Some(Ready(number_added));
            }
            None => break,
        }
    }

    let number_added = Self::recv_many_added_count(buffer.len(), initial_length);
    if number_added > 0 {
        Self::add_many_permits(rx, number_added);
        coop.made_progress();
        Some(Ready(number_added))
    } else {
        None
    }
}

pub(crate) fn chan_recv_many<S: super::chan::Semaphore>(
    rx: &mut super::chan::Rx<T, S>,
    cx: &mut Context<'_>,
    buffer: &mut Vec<T>,
    limit: usize,
) -> Poll<usize> {
    ready!(crate::trace::trace_leaf(cx));
    let coop = ready!(crate::runtime::coop::poll_proceed(cx));

    if Self::recv_many_limit_zero(limit) {
        coop.made_progress();
        return Self::poll_many_ready(0usize);
    }

    let mut remaining = limit;
    let initial_length = buffer.len();

    rx.inner.rx_fields.with_mut(|rx_fields_ptr| {
        let rx_fields = unsafe { &mut *rx_fields_ptr };

        if let Some(ready) = Self::try_fill_recv_many(
            rx,
            rx_fields,
            buffer,
            &mut remaining,
            initial_length,
            &coop,
        ) {
            return ready;
        }

        Self::register_chan_waker(rx, cx);

        if let Some(ready) = Self::try_fill_recv_many(
            rx,
            rx_fields,
            buffer,
            &mut remaining,
            initial_length,
            &coop,
        ) {
            return ready;
        }

        Self::finish_recv_many_after_wait(rx, rx_fields, buffer, &coop)
    })
}

pub(crate) fn map_try_pop_result<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    result: super::list::TryPopResult<T>,
) -> Result<Option<T>, TryRecvError> {
    match result {
        super::list::TryPopResult::Ok(value) => {
            Self::add_single_permit(rx);
            Ok(Some(value))
        }
        super::list::TryPopResult::Closed => Err(Self::try_recv_disconnected()),
        super::list::TryPopResult::Empty => Err(Self::try_recv_empty()),
        super::list::TryPopResult::Busy => Ok(None),
    }
}

pub(crate) fn try_pop_chan_once<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    rx_fields: &mut super::chan::RxFields<T>,
) -> Result<Option<T>, TryRecvError> {
    let result = rx_fields.list.try_pop(&rx.inner.tx);
    Self::try_recv_from_pop(rx, result)
}

pub(crate) fn park_chan_until_ready<S: super::chan::Semaphore>(
    rx: &super::chan::Rx<T, S>,
    rx_fields: &mut super::chan::RxFields<T>,
) -> Result<T, TryRecvError> {
    Self::wake_rx_waker(&rx.inner);
    let mut park = Self::new_cached_park_thread();
    loop {
        Self::register_park_waker(rx, &park);
        match Self::try_pop_chan_once(rx, rx_fields) {
            Ok(Some(value)) => return Ok(value),
            Err(err) => return Err(err),
            Ok(None) => Self::park_thread(&mut park),
        }
    }
}

pub(crate) fn chan_try_recv<S: super::chan::Semaphore>(
    rx: &mut super::chan::Rx<T, S>,
) -> Result<T, TryRecvError> {
    rx.inner.rx_fields.with_mut(|rx_fields_ptr| {
        let rx_fields = unsafe { &mut *rx_fields_ptr };

        match Self::try_pop_chan_once(rx, rx_fields) {
            Ok(Some(value)) => return Ok(value),
            Err(err) => return Err(err),
            Ok(None) => {}
        }

        Self::park_chan_until_ready(rx, rx_fields)
    })
}

pub(crate) fn drain_chan_rx<S: super::chan::Semaphore>(rx: &mut super::chan::Rx<T, S>) {
    rx.inner.rx_fields.with_mut(|rx_fields_ptr| {
        let rx_fields = unsafe { &mut *rx_fields_ptr };
        while let Some(Read::Value(_)) = rx_fields.list.pop(&rx.inner.tx) {
            Self::add_single_permit(rx);
        }
    });
}

pub(crate) fn classify_try_acquire(err: TryAcquireError) -> TrySendError<()> {
    match err {
        TryAcquireError::Closed => Self::try_send_closed(()),
        TryAcquireError::NoPermits => Self::try_send_full(()),
    }
}

pub(crate) fn bounded_try_acquire(
    tx: &super::chan::Tx<T, super::bounded::Semaphore>,
    n: usize,
) -> Result<(), TrySendError<()>> {
    match tx.semaphore().semaphore.try_acquire(n) {
        Ok(()) => Ok(()),
        Err(err) => Err(Self::classify_try_acquire(err)),
    }
}

pub(crate) fn bounded_try_send(
    tx: &super::chan::Tx<T, super::bounded::Semaphore>,
    message: T,
) -> Result<(), TrySendError<T>> {
    match Self::bounded_map_acquire_to_value(Self::bounded_try_acquire(tx, 1), message) {
        Ok(message) => {
            tx.send(message);
            Ok(())
        }
        Err(err) => Err(err),
    }
}

pub(crate) fn bounded_capacity(rx: &super::chan::Rx<T, super::bounded::Semaphore>) -> usize {
    rx.semaphore().semaphore.available_permits()
}

pub(crate) fn bounded_sender_capacity(
    tx: &super::chan::Tx<T, super::bounded::Semaphore>,
) -> usize {
    tx.semaphore().semaphore.available_permits()
}

pub(crate) fn bounded_max_capacity(
    rx: &super::chan::Rx<T, super::bounded::Semaphore>,
) -> usize {
    rx.semaphore().bound
}

pub(crate) fn bounded_sender_max_capacity(
    tx: &super::chan::Tx<T, super::bounded::Semaphore>,
) -> usize {
    tx.semaphore().bound
}

pub(crate) fn bounded_try_reserve_many(
    tx: &super::chan::Tx<T, super::bounded::Semaphore>,
    n: usize,
) -> Result<(), TrySendError<()>> {
    if n > Self::bounded_sender_max_capacity(tx) {
        return Err(TrySendError::Full(()));
    }
    Self::bounded_try_acquire(tx, n)
}

pub(crate) fn unbounded_closed_bit_set(curr: usize) -> bool {
    curr & 1 == 1
}

pub(crate) fn unbounded_count_overflowed(curr: usize) -> bool {
    curr == (usize::MAX ^ 1)
}

pub(crate) fn unbounded_inc_num_messages(
    tx: &super::chan::Tx<T, super::unbounded::Semaphore>,
) -> bool {
    let mut curr = tx.semaphore().0.load(Acquire);

    loop {
        let next = match Self::unbounded_try_add_two(curr) {
            Some(next) => next,
            None => return false,
        };
        match tx
            .semaphore()
            .0
            .compare_exchange(curr, next, AcqRel, Acquire)
        {
            Ok(_) => return true,
            Err(actual) => curr = actual,
        }
    }
}

pub(crate) fn unbounded_send(
    tx: &super::chan::Tx<T, super::unbounded::Semaphore>,
    message: T,
) -> Result<(), SendError<T>> {
    if !Self::unbounded_inc_num_messages(tx) {
        return Err(Self::send_error_from_value(message));
    }
    tx.send(message);
    Ok(())
}

