    block.as_mut().header.start_index = self.header.start_index.wrapping_add(BLOCK_CAP);

    let next_ptr = self
        .header
        .next
        .compare_exchange(ptr::null_mut(), block.as_ptr(), success, failure)
        .unwrap_or_else(|x| x);

